@'
from envparse import parse_env

assert parse_env("A=1\nB = 2 \n") == {"A": "1", "B": "2"}
assert parse_env("# c\n\n   \nA=1") == {"A": "1"}
assert parse_env('A="x\\ny"') == {"A": "x\ny"}
assert parse_env("A='x\\ny'") == {"A": "x\\ny"}
assert parse_env("A=hello  # trailing") == {"A": "hello"}
assert parse_env("A=a#b") == {"A": "a#b"}
assert parse_env("export FOO=bar") == {"FOO": "bar"}
assert parse_env("A=1\nA=2") == {"A": "2"}
assert parse_env("A=") == {"A": ""}
assert parse_env('A="  padded  "') == {"A": "  padded  "}
assert parse_env("URL=https://x/y?a=b") == {"URL": "https://x/y?a=b"}

for src, msg in [
    ("A=1\nnope\n", "invalid line 2: nope"),
    ("1BAD=x", "invalid line 1: 1BAD=x"),
    ("=x", "invalid line 1: =x"),
]:
    try:
        parse_env(src)
    except ValueError as e:
        assert str(e) == msg, (str(e), msg)
    else:
        raise AssertionError(f"no error for {src!r}")

# Extra spot checks
assert parse_env("A=1\r\nB=2\r\n") == {"A": "1", "B": "2"}
assert parse_env('A="a\\qb"') == {"A": "a\\qb"}
assert parse_env('A=""') == {"A": ""}
assert parse_env("A=''") == {"A": ""}
assert parse_env("A=v # c\nB=2") == {"A": "v", "B": "2"}
assert list(parse_env("B=1\nA=2\nB=3")) == ["B", "A"]
print("ALL PASS")
